import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({permit_code:z.string(),day_hikers:z.number().int(),overnight_hikers:z.number().int(),trail_guides:z.number().int(),storm_alert:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({permit_code:v.permit_code,visitor_total:0,trail_units:0,guide_capacity_units:0,admitted_units:0,waiting_units:0,permit_score:0,permit_state:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('authorization')??'')!=="Bearer trail-045")return response(zero(v,'authorization_required'),401,{"www-authenticate":"Bearer realm=trail-permit"});if([v.day_hikers,v.overnight_hikers,v.trail_guides].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.trail_guides===0&&v.day_hikers+v.overnight_hikers>0)return response(zero(v,'invalid'),422,{'x-validation':'trail_guides'});const body=calculate(v);return response(body,200,{'x-permit-state':String(body.permit_state)});};
const app=new Hono();app.get('/status/trail-permit-ready',()=>response({service:'Trail Permit',ready:true}));app.post('/api/v9/trail-permits',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_045_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});

