export type RequestInput={permit_code:string;day_hikers:number;overnight_hikers:number;trail_guides:number;storm_alert:boolean};export const score=(d:number,o:number,g:number,s:boolean)=>{const r=d*5+o*12+(s?g*6:0),c=g*38;return Math.min(r,c)+Math.max(r-c,0)*6};export const calculate=(v:RequestInput)=>{const t=v.day_hikers+v.overnight_hikers,r=v.day_hikers*5+v.overnight_hikers*12+(v.storm_alert?v.trail_guides*6:0),c=v.trail_guides*38,w=Math.max(r-c,0);return {permit_code:v.permit_code,visitor_total:t,trail_units:r,guide_capacity_units:c,admitted_units:Math.min(r,c),waiting_units:w,permit_score:score(v.day_hikers,v.overnight_hikers,v.trail_guides,v.storm_alert),permit_state:w===0?'issued':v.storm_alert?'storm_queue':'routine_queue'}};export async function loadParley(){return {trail_permit_score:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}
